import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero.")

    data = []
    start_time = time.time()
    os_type = platform.system()

    while time.time() - start_time < duration:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        try:
            if os_type == "Windows":
                cmd = "wmic cpu get loadpercentage"
                output = subprocess.check_output(cmd, shell=True).decode().split('\n')[1].strip()
            else:
                cmd = "top -bn1 | grep 'Cpu(s)' | sed 's/.*, *\([0-9.]*\)%* id.*/\1/' | awk '{print 100 - $1}'"
                output = subprocess.check_output(cmd, shell=True).decode().strip()

            data.append({"timestamp": timestamp, "cpu_usage": output})
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import shutil
import os

def task_func(script_path: str, temp_dir: str) -> str:
    if not os.path.exists(script_path):
        return "Script execution failed!"

    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)

    dest_path = os.path.join(temp_dir, os.path.basename(script_path))
    shutil.copy(script_path, dest_path)

    try:
        result = subprocess.run(['python3', dest_path], capture_output=True)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

