import subprocess
import platform
import time

def task_func(url):
    if platform.system() == 'Windows':
        command = ['start', url]
        shell = True
    elif platform.system() == 'Darwin':
        command = ['open', url]
        shell = False
    else:
        command = ['xdg-open', url]
        shell = False

    process = subprocess.Popen(command, shell=shell)
    time.sleep(1)
    return process.poll()

