import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}

    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []

    for file_path in files:
        try:
            subprocess.run(['gzip', '-k', file_path], check=True)
            compressed_file = file_path + '.gz'
            shutil.move(compressed_file, os.path.join(dst_folder, os.path.basename(compressed_file)))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    success = len(failed_files) == 0
    message = 'All files processed successfully' if success else 'Some files failed to process'

    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(['bash', script_path])
    ps_proc = psutil.Process(process.pid)

    cpu_acc = 0.0
    mem_acc = 0
    start_time = time.time()

    while ps_proc.is_running() and (time.time() - start_time) < timeout:
        try:
            cpu_acc += ps_proc.cpu_percent(interval=0.1)
            mem_acc += ps_proc.memory_info().rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
        time.sleep(0.1)

    if ps_proc.is_running():
        ps_proc.terminate()
        ps_proc.wait()

    return {'CPU Usage': cpu_acc, 'Memory Usage': mem_acc}

